<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('storage_locations') ?></h1><div class="<?= $canManage?'grid':'material-browser' ?>"><?php if($canManage): ?><section class="card"><div class="toolbar"><h2><?= $editing?View::t('edit_location'):View::t('new_location') ?></h2><?php if($editing): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/locations"><?= View::t('cancel') ?></a><?php endif; ?></div><form method="post" action="<?= View::e($basePath) ?><?= $editing?'/locations/'.View::e($editing['id']):'/locations' ?>"><?= View::csrf() ?><label><?= View::t('name') ?><input name="name" required maxlength="120" value="<?= View::e($editing['name']??'') ?>"></label><label><?= View::t('code') ?><input name="code" maxlength="60" value="<?= View::e($editing['code']??'') ?>"></label><label><?= View::t('parent_location') ?><select name="parent_id"><option value="">—</option><?php foreach($locations as $l): if($editing&&$l['id']===$editing['id'])continue; ?><option value="<?= View::e($l['id']) ?>" <?= ($editing['parent_id']??'')===$l['id']?'selected':'' ?>><?= View::e($l['name']) ?></option><?php endforeach; ?></select></label><label><?= View::t('description') ?><input name="description" maxlength="255" value="<?= View::e($editing['description']??'') ?>"></label><button class="action-button"><?= View::t('save') ?></button></form></section><?php endif; ?><section><div class="table-wrap"><table><thead><tr><th><?= View::t('name') ?></th><th><?= View::t('code') ?></th><th><?= View::t('parent_location') ?></th><th><?= View::t('spool_count') ?></th><th></th></tr></thead><tbody><?php foreach($locations as $l): ?><tr><td><?= View::e($l['name']) ?></td><td><?= View::e($l['code']) ?></td><td><?= View::e($l['parent_name']??'—') ?></td><td><?= View::e($l['spool_count']) ?></td><td><?php if($canManage): ?><div class="actions"><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/locations/<?= View::e($l['id']) ?>/edit"><?= View::t('edit') ?></a><form method="post" action="<?= View::e($basePath) ?>/locations/<?= View::e($l['id']) ?>/delete"><?= View::csrf() ?><button class="danger-button action-button"><?= View::t('delete') ?></button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
